class Solution:
    def numWays(self, s: str) -> int:
        MOD = 10 ** 9 + 7
        n = len(s)
        counts = s.count('1')
        if counts % 3 != 0:
            return 0

        if counts == 0:
            return (n - 1) * (n - 2) // 2

        num = counts // 3

        total = 0
        p1 = 0
        p2 = 0

        for i in range(n):
            if s[i] == '1':
                total += 1
            if total == num:
                p1 += 1
            if total == 2 * num:
                p2 += 1

        return p1 * p2 % MOD
s=""
